with r as (select 'inbox_items' src,to_jsonb(t) j from public.inbox_items t where organisation_id='__TENANT_UUID__' union all select 'growth_targets' src,to_jsonb(t) j from public.growth_targets t where organisation_id='__TENANT_UUID__' union all select 'acquisition_items' src,to_jsonb(t) j from public.acquisition_items t where organisation_id='__TENANT_UUID__' union all select 'founder_research_records' src,to_jsonb(t) j from public.founder_research_records t where organisation_id='__TENANT_UUID__' union all select 'founder_activity_events' src,to_jsonb(t) j from public.founder_activity_events t where organisation_id='__TENANT_UUID__' union all select 'email_conversation_messages' src,to_jsonb(t) j from public.email_conversation_messages t where organisation_id='__TENANT_UUID__' union all select 'linkedin_conversation_messages' src,to_jsonb(t) j from public.linkedin_conversation_messages t where organisation_id='__TENANT_UUID__' union all select 'relationship_workspaces' src,to_jsonb(t) j from public.relationship_workspaces t where organisation_id='__TENANT_UUID__' union all select 'relationship_source_links' src,to_jsonb(t) j from public.relationship_source_links t where organisation_id='__TENANT_UUID__' union all select 'relationship_activity_events' src,to_jsonb(t) j from public.relationship_activity_events t where organisation_id='__TENANT_UUID__' union all select 'relationship_tasks' src,to_jsonb(t) j from public.relationship_tasks t where organisation_id='__TENANT_UUID__' union all select 'acquisition_item_events' src,to_jsonb(t) j from public.acquisition_item_events t where organisation_id='__TENANT_UUID__' union all select 'response_item_events' src,to_jsonb(t) j from public.response_item_events t where organisation_id='__TENANT_UUID__'), selected as (select * from r), clean as (select src, (select jsonb_object_agg(k,v) from jsonb_each(j) e(k,v) where k=any(array['id','record_type','entity','author_handle','engine_observed_at','current_action','actioned_at'